@startuml

class Library {
}

class User {
  + security_deposit : float
  + phone : string
  + email : string
}

class BorrowableItem {
  + libraryCode : int
}

class Location {
  + bookcase : int
  + shelf : int
}

class Book {
  + publisher : string
}

class Author {
  + name : string
}

class MagazineIssue {
  + publication_date : date
  + publisher : string
}

class CD {
  + publisher : string
  + artist : string
}

class Film {
  + duration : time
  + publisher : string
}

class VHS {
}

class DVD extends Film {
}

class ItemTransferRequest {
}

Library "1" -- "*" User : has
Library "1" -- "*" BorrowableItem : contains
Library "0..1" -- "*" ItemTransferRequest : destination
Library "0..1" -- "*" ItemTransferRequest : source

User "0..1" -- "0..3" BorrowableItem : borrows
BorrowableItem "0..1" -- "0..1" User : lent to
BorrowableItem "1" -- "1" Location : located at
BorrowableItem "0..*" -- "0..1" ItemTransferRequest : requested

Book "1" -- "1..*" Author : has
Book "*" -- "1" BorrowableItem : is a
MagazineIssue "*" -- "1" BorrowableItem : is a
CD "*" -- "1" BorrowableItem : is a
VHS "*" -- "1" BorrowableItem : is a
Film "*" -- "1" BorrowableItem : is a
Film "1" -- "*" Actor : has

@enduml

